// Chat-Layout (Vorgabe Stefan, 11.10.2026): Titel fett mit Doppelpunkt, Inhalt direkt darunter, Leerzeile zwischen Bloecken, keine Listenpunkte, keine Emojis
const esc = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const roh = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '');
const zeileHtml = z => typeof z === 'string' ? esc(z) : (z.html !== undefined ? z.html : (z.kursiv ? '<em>' + esc(z.t) + '</em>' : esc(z.t)));
const zeileText = z => typeof z === 'string' ? roh(z) : (z.behalten ? String(z.t ?? '') : roh(z.t));
const render = bloecke => {
  const b = bloecke.filter(x => x && (x.titel || (x.zeilen || []).length));
  return {
    html: b.map(x => (x.titel ? '<strong>' + esc(x.titel) + '</strong>' + ((x.zeilen || []).length ? '<br>' : '') : '') + (x.zeilen || []).map(zeileHtml).join('<br>')).join('<br><br>'),
    text: b.map(x => (x.titel ? roh(x.titel) + ((x.zeilen || []).length ? '\n' : '') : '') + (x.zeilen || []).map(zeileText).join('\n')).join('\n\n')
  };
};
const m = $('Start durch MAIL 2').first().json;
// Zusammenfassung: normal kommt sie über "KI-Verbrauch buchen" (Feld content). Ist die Zusammenfassung gescheitert,
// kommt der Aufruf über den Fehlerausgang ohne content; dann geht das Angebot ohne Kurzfassung raus.
// (Fehler vom 13.10.: $('Mail zusammenfassen').first() las den Fehlerausgang und fand nie eine Zusammenfassung.)
let c = (($input.first() || {}).json || {}).content;
if (!Array.isArray(c)) {
  try { c = $('Mail zusammenfassen').first(0).json.content; } catch (e) { c = []; }
}
const zusammenfassung = (Array.isArray(c) ? c : []).filter(b => b && b.type === 'text' && b.text).map(b => String(b.text)).join(' ').replace(/[\p{Extended_Pictographic}️‍]/gu, '').replace(/ {2,}/g, ' ').trim();
const postfach = String(m.postfach || '');
const adresse = m.antwort_an || m.absender || '';

return $('Empfänger prüfen und Mail anlegen').all().map(i => {
  const r = i.json;
  const ref = 'mail-' + r.id;
  const n = render([
    { titel: 'Neue Mail an ' + postfach + ':', zeilen: [m.absender_name, adresse].filter(Boolean) },
    { titel: 'Betreff:', zeilen: [m.betreff || '(ohne Betreff)'] },
    { titel: 'Zusammenfassung:', zeilen: [zusammenfassung || '(Kurzfassung gerade nicht verfügbar)'] },
    { titel: 'Antwort vorbereiten?', zeilen: ['Antworte direkt auf diese Nachricht mit „ja“ oder ein paar Stichpunkten, „nein“ wenn nicht.'] },
    { zeilen: ['Referenz: ' + ref] }
  ]);
  return { json: { rueckfrage_id: r.id, user_id: r.user_id, room_id: r.room_id, text: n.text, html: n.html, zusammenfassung } };
});

